//! ABI layout check (design §13): size, alignment and field offsets of every
//! `#[repr(C)]` struct against the Linux UAPI layout, for BOTH arches,
//! whatever the host arch is.
//!
//! Sources of the expected values (no Linux headers on the dev host):
//!
//! - [X] `golang.org/x/sys@v0.48.0/unix/ztypes_linux_{amd64,arm64}.go`,
//!   generated by `cgo -godefs` from the real UAPI headers; sizes/offsets
//!   computed with `go/types` `SizesFor("gc", arch)` (all those structs
//!   carry explicit padding, so gc layout equals C layout).
//! - [R] Go `runtime/defs_linux_{amd64,arm64}.go` (also `cgo -godefs`): the
//!   signal structs Go's runtime actually reads (`sigcontext`, `ucontext`,
//!   `siginfo`, `sigactiont`, `stackt`, `sigevent`, `fpstate`).
//! - [K] Hand-derived from the kernel UAPI header named in the comment,
//!   where neither Go source models the kernel struct (`rt_sigframe`, the
//!   arm64 `__reserved` records, x86 kernel `ucontext` tail).
//!
//! C alignment is noted where it differs from what Go reports (Go models
//! `__u64`-in-packed and `__uint128_t` fields differently).

use core::mem::{align_of, offset_of, size_of};

use crate::{aarch64 as a64, fs, misc, net, signal, time, x86_64 as x64};

macro_rules! check {
    ($t:ty, size = $s:expr, align = $a:expr $(, $($f:ident).+ = $o:expr)* $(,)?) => {{
        assert_eq!(size_of::<$t>(), $s, concat!("sizeof(", stringify!($t), ")"));
        assert_eq!(align_of::<$t>(), $a, concat!("alignof(", stringify!($t), ")"));
        $(
            assert_eq!(
                offset_of!($t, $($f).+),
                $o,
                concat!("offsetof(", stringify!($t), ", ", stringify!($($f).+), ")")
            );
        )*
    }};
}

// ---------------------------------------------------------------- common --

#[test]
fn timespec_family() {
    // [X] Timespec/Timeval/Itimerval/ItimerSpec, both arches.
    check!(
        time::Timespec,
        size = 16,
        align = 8,
        tv_sec = 0,
        tv_nsec = 8
    );
    check!(time::Timeval, size = 16, align = 8, tv_sec = 0, tv_usec = 8);
    check!(
        time::Itimerval,
        size = 32,
        align = 8,
        it_interval = 0,
        it_value = 16
    );
    check!(
        time::Itimerspec,
        size = 32,
        align = 8,
        it_interval = 0,
        it_value = 16
    );
    // [K] include/uapi/linux/time.h struct timezone { int; int; }
    check!(
        time::Timezone,
        size = 8,
        align = 4,
        tz_minuteswest = 0,
        tz_dsttime = 4
    );
}

#[test]
fn signal_structs() {
    // [R] sigactiont: sa_handler 0, sa_flags 8, sa_restorer 16, sa_mask 24; size 32 (both arches).
    check!(
        signal::SigAction,
        size = 32,
        align = 8,
        sa_handler = 0,
        sa_flags = 8,
        sa_restorer = 16,
        sa_mask = 24
    );
    // [R] stackt: ss_sp 0, ss_flags 8, ss_size 16; size 24.
    check!(
        signal::StackT,
        size = 24,
        align = 8,
        ss_sp = 0,
        ss_flags = 8,
        ss_size = 16
    );
    // [X] Siginfo: 128 bytes, signo 0, errno 4, code 8, union at 16
    // ([R] siginfoFields.si_addr at 16). C alignment is 8 (union has pointers).
    check!(
        signal::SigInfo,
        size = 128,
        align = 8,
        si_signo = 0,
        si_errno = 4,
        si_code = 8,
        fields = 16
    );
    // [R] sigevent: value 0, signo 8, notify 12, sigev_notify_thread_id 16; size 64
    // (SIGEV_MAX_SIZE, include/uapi/asm-generic/siginfo.h).
    check!(
        signal::SigEvent,
        size = 64,
        align = 8,
        sigev_value = 0,
        sigev_signo = 8,
        sigev_notify = 12,
        un = 16
    );
}

#[test]
fn fs_structs() {
    // [X] Statx_t / StatxTimestamp (identical on both arches).
    check!(
        fs::StatxTimestamp,
        size = 16,
        align = 8,
        tv_sec = 0,
        tv_nsec = 8
    );
    check!(
        fs::Statx,
        size = 256,
        align = 8,
        stx_mask = 0,
        stx_blksize = 4,
        stx_attributes = 8,
        stx_nlink = 16,
        stx_uid = 20,
        stx_gid = 24,
        stx_mode = 28,
        stx_ino = 32,
        stx_size = 40,
        stx_blocks = 48,
        stx_attributes_mask = 56,
        stx_atime = 64,
        stx_btime = 80,
        stx_ctime = 96,
        stx_mtime = 112,
        stx_rdev_major = 128,
        stx_rdev_minor = 132,
        stx_dev_major = 136,
        stx_dev_minor = 140,
        stx_mnt_id = 144,
        stx_dio_mem_align = 152,
        stx_dio_offset_align = 156,
        _spare = 160,
    );
    // [X] Iovec, PollFd, Flock_t.
    check!(fs::Iovec, size = 16, align = 8, iov_base = 0, iov_len = 8);
    check!(
        fs::PollFd,
        size = 8,
        align = 4,
        fd = 0,
        events = 4,
        revents = 6
    );
    check!(
        fs::Flock,
        size = 32,
        align = 8,
        l_type = 0,
        l_whence = 2,
        l_start = 8,
        l_len = 16,
        l_pid = 24
    );
    // [X] Dirent (linux_dirent64): Ino 0, Off 8, Reclen 16, Type 18, Name 19.
    assert_eq!(fs::DIRENT64_INO_OFFSET, 0);
    assert_eq!(fs::DIRENT64_OFF_OFFSET, 8);
    assert_eq!(fs::DIRENT64_RECLEN_OFFSET, 16);
    assert_eq!(fs::DIRENT64_TYPE_OFFSET, 18);
    assert_eq!(fs::DIRENT64_NAME_OFFSET, 19);
}

