#[test]
fn x86_64_epoll_event() {
    // [X] amd64 EpollEvent: 12 bytes, data at 4 (EPOLL_PACKED). C align is 1
    // (__attribute__((packed))); Go reports 4 because it splits data into int32s.
    check!(x64::EpollEvent, size = 12, align = 1, events = 0, data = 4);
}

#[test]
fn x86_64_signal_frame() {
    // [R] amd64 sigcontext: r8 0 .. rsp 120, rip 128, eflags 136, cs 144, gs 146,
    // fs 148, __pad0/ss 150, err 152, trapno 160, oldmask 168, cr2 176,
    // fpstate 184, __reserved1 192; size 256.
    check!(
        x64::SigContext,
        size = 256,
        align = 8,
        r8 = 0,
        r9 = 8,
        r10 = 16,
        r11 = 24,
        r12 = 32,
        r13 = 40,
        r14 = 48,
        r15 = 56,
        rdi = 64,
        rsi = 72,
        rbp = 80,
        rbx = 88,
        rdx = 96,
        rax = 104,
        rcx = 112,
        rsp = 120,
        rip = 128,
        eflags = 136,
        cs = 144,
        gs = 146,
        fs = 148,
        ss = 150,
        err = 152,
        trapno = 160,
        oldmask = 168,
        cr2 = 176,
        fpstate = 184,
        reserved1 = 192
    );
    // [R] amd64 fpstate (512): cwd 0, swd 2, ftw 4, fop 6, rip 8, rdp 16,
    // mxcsr 24, mxcr_mask 28, _st 32, _xmm 160, padding 416.
    // [K] arch/x86/include/uapi/asm/sigcontext.h _fpstate_64: reserved2[12]
    // at 416, sw_reserved (struct _fpx_sw_bytes, 48 bytes) at 464.
    check!(
        x64::FpState,
        size = 512,
        align = 8,
        cwd = 0,
        swd = 2,
        twd = 4,
        fop = 6,
        rip = 8,
        rdp = 16,
        mxcsr = 24,
        mxcsr_mask = 28,
        st_space = 32,
        xmm_space = 160,
        reserved2 = 416,
        sw_reserved = 464
    );
    // [K] struct _fpx_sw_bytes: magic1 0, extended_size 4, xfeatures 8,
    // xstate_size 16, padding[7] 20; size 48.
    check!(
        x64::FpxSwBytes,
        size = 48,
        align = 8,
        magic1 = 0,
        extended_size = 4,
        xfeatures = 8,
        xstate_size = 16,
        padding = 20
    );
    // [R] amd64 ucontext: uc_flags 0, uc_link 8, uc_stack 16, uc_mcontext 40,
    // uc_sigmask 296. [K] the kernel's struct ucontext ends after an 8-byte
    // sigset_t (arch/x86/include/uapi/asm/ucontext.h) => 304; Go's 936 is
    // glibc's ucontext_t (128-byte sigset + __fpregs_mem).
    check!(
        x64::UContext,
        size = 304,
        align = 8,
        uc_flags = 0,
        uc_link = 8,
        uc_stack = 16,
        uc_mcontext = 40,
        uc_sigmask = 296,
        uc_mcontext.rip = 168,
        uc_mcontext.rsp = 160,
        uc_mcontext.fpstate = 224
    );
    // [K] arch/x86/include/asm/sigframe.h (64-bit): pretcode 0, uc 8, info 312.
    check!(
        x64::RtSigframe,
        size = 440,
        align = 8,
        pretcode = 0,
        uc = 8,
        info = 312
    );
}

