#[test]
fn aarch64_signal_frame() {
    // [R] arm64 sigcontext: fault_address 0, regs 8, sp 256, pc 264,
    // pstate 272, _pad 280, __reserved 288 (aligned(16)); size 4384.
    check!(
        a64::SigContext,
        size = 4384,
        align = 16,
        fault_address = 0,
        regs = 8,
        sp = 256,
        pc = 264,
        pstate = 272,
        reserved = 288
    );
    // [K] arch/arm64/include/uapi/asm/sigcontext.h: _aarch64_ctx {magic, size}.
    check!(a64::Aarch64Ctx, size = 8, align = 4, magic = 0, size = 4);
    // [K] fpsimd_context: head 0, fpsr 8, fpcr 12, vregs 16 (__uint128_t,
    // 16-aligned); size 528 (0x210), align 16.
    check!(
        a64::FpsimdContext,
        size = 528,
        align = 16,
        head = 0,
        fpsr = 8,
        fpcr = 12,
        vregs = 16
    );
    // [K] esr_context: head 0, esr 8; size 16.
    check!(a64::EsrContext, size = 16, align = 8, head = 0, esr = 8);
    // [R] arm64 ucontext: uc_flags 0, uc_link 8, uc_stack 16, uc_sigmask 40,
    // __unused 48 (120 bytes), padding 168, uc_mcontext 176; size 4560.
    check!(
        a64::UContext,
        size = 4560,
        align = 16,
        uc_flags = 0,
        uc_link = 8,
        uc_stack = 16,
        uc_sigmask = 40,
        _unused = 48,
        uc_mcontext = 176,
        uc_mcontext.regs = 184,
        uc_mcontext.sp = 432,
        uc_mcontext.pc = 440,
        uc_mcontext.reserved = 464
    );
    // [K] arch/arm64/kernel/signal.c struct rt_sigframe { siginfo info; ucontext uc; }.
    check!(a64::RtSigframe, size = 4688, align = 16, info = 0, uc = 128);
    check!(a64::FrameRecord, size = 16, align = 8, fp = 0, lr = 8);
    // FPSIMD record must fit in __reserved with room for ESR + terminator.
    const _: () = assert!(528 + 16 + 8 <= a64::SIGCONTEXT_RESERVED_SIZE);
}

// ------------------------------------------------- arch-identical consts --

#[test]
fn consts_cross_arch() {
    // Verified equal on amd64 and arm64 in x/sys zerrors (diffed): signal
    // numbers, SA_*, MAP_* (except MAP_32BIT/ABOVE4G), MADV_*, EPOLL*, SOCK_*,
    // SO_*, MSG_*, F_*, FUTEX_*, CLONE_*, errno. Only O_DIRECT, O_DIRECTORY,
    // O_NOFOLLOW, O_TMPFILE, O_LARGEFILE and PROT_BTI/MTE differ.
    assert_eq!(signal::SIGURG, 23);
    assert_eq!(signal::SIGPROF, 27);
    assert_eq!(signal::SaFlags::ONSTACK.bits(), 0x0800_0000);
    assert_eq!(signal::SaFlags::RESTORER.bits(), 0x0400_0000);
    assert_eq!(crate::mm::MapFlags::FIXED_NOREPLACE.bits(), 0x10_0000);
    assert_eq!(crate::mm::MADV_COLLAPSE, 25);
    assert_eq!(crate::epoll::EpollFlags::ET.bits(), 0x8000_0000);
    assert_eq!(net::SOCK_NONBLOCK, 0x800);
    assert_eq!(net::SOCK_CLOEXEC, 0x80000);
    assert_eq!(net::SO_RCVTIMEO_OLD, 0x14);
    assert_eq!(net::MsgFlags::NOSIGNAL.bits(), 0x4000);
    assert_eq!(fs::O_SYNC, 0x101000);
    assert_eq!(fs::O_PATH, 0x200000);
    assert_eq!(fs::O_NOATIME, 0x40000);
    assert_eq!(misc::TIOCGWINSZ, 0x5413);
    assert_eq!(x64::MINSIGSTKSZ, 2048);
    assert_eq!(a64::MINSIGSTKSZ, 5120);
}
